const i = $input.first().json;
const periodo = String(i.periodo ?? '').trim();
const hoy = $now.setZone('Europe/Madrid').startOf('day');
const fmt = (d) => d.toFormat('yyyy-MM-dd');
let desde;
let hasta;

switch (periodo) {
  case 'hoy': desde = hasta = hoy; break;
  case 'manana': desde = hasta = hoy.plus({ days: 1 }); break;
  case 'esta_semana':
    desde = hoy.startOf('week');
    hasta = desde.plus({ days: 6 });
    break;
  case 'proxima_semana':
    desde = hoy.startOf('week').plus({ weeks: 1 });
    hasta = desde.plus({ days: 6 });
    break;
  case 'este_mes':
    desde = hoy.startOf('month');
    hasta = hoy.endOf('month').startOf('day');
    break;
  case 'mes_siguiente':
    desde = hoy.startOf('month').plus({ months: 1 });
    hasta = desde.endOf('month').startOf('day');
    break;
  case 'proximos_dias': {
    const n = Number(i.dias);
    if (!Number.isInteger(n) || n < 1 || n > 366) throw new Error(`Dias no válido: ${i.dias}`);
    desde = hoy;
    hasta = hoy.plus({ days: n });
    break;
  }
  case 'rango': {
    desde = DateTime.fromISO(String(i.desde), { zone: 'Europe/Madrid' });
    hasta = DateTime.fromISO(String(i.hasta), { zone: 'Europe/Madrid' });
    if (!desde.isValid || !hasta.isValid) throw new Error(`Fechas no válidas: ${i.desde} / ${i.hasta}`);
    if (desde > hasta) throw new Error(`Rango no válido: ${i.desde} / ${i.hasta}`);
    break;
  }
  default:
    throw new Error(`Periodo desconocido: ${periodo}`);
}

return [{ json: { periodo, hoy: fmt(hoy), desde: fmt(desde), hasta: fmt(hasta) } }];

const f = $('Calcular fechas').first().json;
const MAX = 30;
const fecha = (s) => s.split('-').reverse().join('/');
const euros = (n) =>
  `${Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} €`;

const lista = $('Apartados activos').all()
  .map((i) => i.json)
  .filter((a) => a.id !== undefined && a.fecha_limite >= f.desde && a.fecha_limite <= f.hasta);

const rango = f.desde === f.hasta
  ? `El ${fecha(f.desde)}`
  : `Del ${fecha(f.desde)} al ${fecha(f.hasta)}`;

const linea = (a) =>
  `- #${a.id} ${a.cliente}: ${a.producto} (talla ${a.talla}) · pendiente ${euros(a.pendiente)} · límite ${fecha(a.fecha_limite)}` +
  (a.fecha_limite < f.hoy ? ' (plazo ya pasado, sigue activo)' : '');

const lineas = lista.slice(0, MAX).map(linea);
if (lista.length > MAX) lineas.push(`… y ${lista.length - MAX} más`);

const texto = lista.length === 0
  ? `${rango} no vence ningún apartado activo`
  : `${rango} vencen ${lista.length} apartado(s) activo(s):\n\n${lineas.join('\n')}`;

return [{ json: { periodo: f.periodo, desde: f.desde, hasta: f.hasta, apartados: lista.length, texto } }];
